        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug occurs when the `TCP_REPAIR_OPTIONS` is set after data has already been sent on a socket, leading to an inconsistency in the TCP state management. Specifically, enabling SACK after data transmission causes the `tcp_timeout_mark_lost()` function to trigger a warning due to the mismatch between the number of lost packets and the number of packets sent, as the state of the socket does not account for previously sent data. This results in an invalid state where the socket is trying to repair options that should not be modified post data transmission.

        Commit message:
        tcp: prohibit TCP_REPAIR_OPTIONS if data was already sent

If setsockopt with option name of TCP_REPAIR_OPTIONS and opt_code
of TCPOPT_SACK_PERM is called to enable sack after data is sent
and dupacks are received , it will trigger a warning in function
tcp_verify_left_out() as follows:

============================================
WARNING: CPU: 8 PID: 0 at net/ipv4/tcp_input.c:2132
tcp_timeout_mark_lost+0x154/0x160
tcp_enter_loss+0x2b/0x290
tcp_retransmit_timer+0x50b/0x640
tcp_write_timer_handler+0x1c8/0x340
tcp_write_timer+0xe5/0x140
call_timer_fn+0x3a/0x1b0
__run_timers.part.0+0x1bf/0x2d0
run_timer_softirq+0x43/0xb0
__do_softirq+0xfd/0x373
__irq_exit_rcu+0xf6/0x140

The warning is caused in the following steps:
1. a socket named socketA is created
2. socketA enters repair mode without build a connection
3. socketA calls connect() and its state is changed to TCP_ESTABLISHED
   directly
4. socketA leaves repair mode
5. socketA calls sendmsg() to send data, packets_out and sack_outs(dup
   ack receives) increase
6. socketA enters repair mode again
7. socketA calls setsockopt with TCPOPT_SACK_PERM to enable sack
8. retransmit timer expires, it calls tcp_timeout_mark_lost(), lost_out
   increases
9. sack_outs + lost_out > packets_out triggers since lost_out and
   sack_outs increase repeatly

In function tcp_timeout_mark_lost(), tp->sacked_out will be cleared if
Step7 not happen and the warning will not be triggered. As suggested by
Denis and Eric, TCP_REPAIR_OPTIONS should be prohibited if data was
already sent.

socket-tcp tests in CRIU has been tested as follows:
$ sudo ./test/zdtm.py run -t zdtm/static/socket-tcp*  --keep-going \
       --ignore-taint

socket-tcp* represent all socket-tcp tests in test/zdtm/static/.

Fixes: b139ba4e90dc ("tcp: Repair connection-time negotiated parameters")
Signed-off-by: Lu Wei <luwei32@huawei.com>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:
          */
 int do_tcp_setsockopt(struct sock *sk, int level, int optname,
 		      sockptr_t optval, unsigned int optlen)
 {
 	struct tcp_sock *tp = tcp_sk(sk);
 	struct inet_connection_sock *icsk = inet_csk(sk);
 	struct net *net = sock_net(sk);
 	int val;
 	int err = 0;

 	/* These are data/string values, all the others are ints */
 	switch (optname) {
 	case TCP_CONGESTION: {
 		char name[TCP_CA_NAME_MAX];

 		if (optlen < 1)
 			return -EINVAL;

 		val = strncpy_from_sockptr(name, optval,
 					min_t(long, TCP_CA_NAME_MAX-1, optlen));
 		if (val < 0)
 			return -EFAULT;
 		name[val] = 0;

 		sockopt_lock_sock(sk);
 		err = tcp_set_congestion_control(sk, name, !has_current_bpf_ctx(),
 						 sockopt_ns_capable(sock_net(sk)->user_ns,
 								    CAP_NET_ADMIN));
 		sockopt_release_sock(sk);
 		return err;
 	}
 	case TCP_ULP: {
 		char name[TCP_ULP_NAME_MAX];

 		if (optlen < 1)
 			return -EINVAL;

 		val = strncpy_from_sockptr(name, optval,
 					min_t(long, TCP_ULP_NAME_MAX - 1,
 					      optlen));
 		if (val < 0)
 			return -EFAULT;
 		name[val] = 0;

 		sockopt_lock_sock(sk);
 		err = tcp_set_ulp(sk, name);
 		sockopt_release_sock(sk);
 		return err;
 	}
 	case TCP_FASTOPEN_KEY: {
 		__u8 key[TCP_FASTOPEN_KEY_BUF_LENGTH];
 		__u8 *backup_key = NULL;

 		/* Allow a backup key as well to facilitate key rotation
 		 * First key is the active one.
 		 */
 		if (optlen != TCP_FASTOPEN_KEY_LENGTH &&
 		    optlen != TCP_FASTOPEN_KEY_BUF_LENGTH)
 			return -EINVAL;

 		if (copy_from_sockptr(key, optval, optlen))
 			return -EFAULT;

 		if (optlen == TCP_FASTOPEN_KEY_BUF_LENGTH)
 			backup_key = key + TCP_FASTOPEN_KEY_LENGTH;

 		return tcp_fastopen_reset_cipher(net, sk, key, backup_key);
 	}
 	default:
 		/* fallthru */
 		break;
 	}

 	if (optlen < sizeof(int))
 		return -EINVAL;

 	if (copy_from_sockptr(&val, optval, sizeof(val)))
 		return -EFAULT;

 	sockopt_lock_sock(sk);

 	switch (optname) {
 	case TCP_MAXSEG:
 		/* Values greater than interface MTU won't take effect. However
 		 * at the point when this call is done we typically don't yet
 		 * know which interface is going to be used
 		 */
 		if (val && (val < TCP_MIN_MSS || val > MAX_TCP_WINDOW)) {
 			err = -EINVAL;
 			break;
 		}
 		tp->rx_opt.user_mss = val;
 		break;

 	case TCP_NODELAY:
 		__tcp_sock_set_nodelay(sk, val);
 		break;

 	case TCP_THIN_LINEAR_TIMEOUTS:
 		if (val < 0 || val > 1)
 			err = -EINVAL;
 		else
 			tp->thin_lto = val;
 		break;

 	case TCP_THIN_DUPACK:
 		if (val < 0 || val > 1)
 			err = -EINVAL;
 		break;

 	case TCP_REPAIR:
 		if (!tcp_can_repair_sock(sk))
 			err = -EPERM;
 		else if (val == TCP_REPAIR_ON) {
 			tp->repair = 1;
 			sk->sk_reuse = SK_FORCE_REUSE;
 			tp->repair_queue = TCP_NO_QUEUE;
 		} else if (val == TCP_REPAIR_OFF) {
 			tp->repair = 0;
 			sk->sk_reuse = SK_NO_REUSE;
 			tcp_send_window_probe(sk);
 		} else if (val == TCP_REPAIR_OFF_NO_WP) {
 			tp->repair = 0;
 			sk->sk_reuse = SK_NO_REUSE;
 		} else
 			err = -EINVAL;

 		break;

 	case TCP_REPAIR_QUEUE:
 		if (!tp->repair)
 			err = -EPERM;
 		else if ((unsigned int)val < TCP_QUEUES_NR)
 			tp->repair_queue = val;
 		else
 			err = -EINVAL;
 		break;

 	case TCP_QUEUE_SEQ:
 		if (sk->sk_state != TCP_CLOSE) {
 			err = -EPERM;
 		} else if (tp->repair_queue == TCP_SEND_QUEUE) {
 			if (!tcp_rtx_queue_empty(sk))
 				err = -EPERM;
 			else
 				WRITE_ONCE(tp->write_seq, val);
 		} else if (tp->repair_queue == TCP_RECV_QUEUE) {
 			if (tp->rcv_nxt != tp->copied_seq) {
 				err = -EPERM;
 			} else {
 				WRITE_ONCE(tp->rcv_nxt, val);
 				WRITE_ONCE(tp->copied_seq, val);
 			}
 		} else {
 			err = -EINVAL;
 		}
 		break;

 	case TCP_REPAIR_OPTIONS:
 		if (!tp->repair)
 			err = -EINVAL;
-		else if (sk->sk_state == TCP_ESTABLISHED)
+		else if (sk->sk_state == TCP_ESTABLISHED && !tp->bytes_sent)
 			err = tcp_repair_options_est(sk, optval, optlen);
 		else
 			err = -EPERM;
 		break;

 	case TCP_CORK:
 		__tcp_sock_set_cork(sk, val);
 		break;

 	case TCP_KEEPIDLE:
 		err = tcp_sock_set_keepidle_locked(sk, val);
 		break;
 	case TCP_KEEPINTVL:
 		if (val < 1 || val > MAX_TCP_KEEPINTVL)
 			err = -EINVAL;
 		else
 			tp->keepalive_intvl = val * HZ;
 		break;
 	case TCP_KEEPCNT:
 		if (val < 1 || val > MAX_TCP_KEEPCNT)
 			err = -EINVAL;
 		else
 			tp->keepalive_probes = val;
 		break;
 	case TCP_SYNCNT:
 		if (val < 1 || val > MAX_TCP_SYNCNT)
 			err = -EINVAL;
 		else
 			icsk->icsk_syn_retries = val;
 		break;

 	case TCP_SAVE_SYN:
 		/* 0: disable, 1: enable, 2: start from ether_header */
 		if (val < 0 || val > 2)
 			err = -EINVAL;
 		else
 			tp->save_syn = val;
 		break;

 	case TCP_LINGER2:
 		if (val < 0)
 			tp->linger2 = -1;
 		else if (val > TCP_FIN_TIMEOUT_MAX / HZ)
 			tp->linger2 = TCP_FIN_TIMEOUT_MAX;
 		else
 			tp->linger2 = val * HZ;
 		break;

 	case TCP_DEFER_ACCEPT:
 		/* Translate value in seconds to number of retransmits */
 		icsk->icsk_accept_queue.rskq_defer_accept =
 			secs_to_retrans(val, TCP_TIMEOUT_INIT / HZ,
 					TCP_RTO_MAX / HZ);
 		break;

 	case TCP_WINDOW_CLAMP:
 		err = tcp_set_window_clamp(sk, val);
 		break;

 	case TCP_QUICKACK:
 		__tcp_sock_set_quickack(sk, val);
 		break;

 #ifdef CONFIG_TCP_MD5SIG
 	case TCP_MD5SIG:
 	case TCP_MD5SIG_EXT:
 		err = tp->af_specific->md5_parse(sk, optname, optval, optlen);
 		break;
 #endif
 	case TCP_USER_TIMEOUT:
 		/* Cap the max time in ms TCP will retry or probe the window
 		 * before giving up and aborting (ETIMEDOUT) a connection.
 		 */
 		if (val < 0)
 			err = -EINVAL;
 		else
 			icsk->icsk_user_timeout = val;
 		break;

 	case TCP_FASTOPEN:
 		if (val >= 0 && ((1 << sk->sk_state) & (TCPF_CLOSE |
 		    TCPF_LISTEN))) {
 			tcp_fastopen_init_key_once(net);

 			fastopen_queue_tune(sk, val);
 		} else {
 			err = -EINVAL;
 		}
 		break;
 	case TCP_FASTOPEN_CONNECT:
 		if (val > 1 || val < 0) {
 			err = -EINVAL;
 		} else if (READ_ONCE(net->ipv4.sysctl_tcp_fastopen) &
 			   TFO_CLIENT_ENABLE) {
 			if (sk->sk_state == TCP_CLOSE)
 				tp->fastopen_connect = val;
 			else
 				err = -EINVAL;
 		} else {
 			err = -EOPNOTSUPP;
 		}
 		break;
 	case TCP_FASTOPEN_NO_COOKIE:
 		if (val > 1 || val < 0)
 			err = -EINVAL;
 		else if (!((1 << sk->sk_state) & (TCPF_CLOSE | TCPF_LISTEN)))
 			err = -EINVAL;
 		else
 			tp->fastopen_no_cookie = val;
 		break;
 	case TCP_TIMESTAMP:
 		if (!tp->repair)
 			err = -EPERM;
 		else
 			tp->tsoffset = val - tcp_time_stamp_raw();
 		break;
 	case TCP_REPAIR_WINDOW:
 		err = tcp_repair_set_window(tp, optval, optlen);
 		break;
 	case TCP_NOTSENT_LOWAT:
 		tp->notsent_lowat = val;
 		sk->sk_write_space(sk);
 		break;
 	case TCP_INQ:
 		if (val > 1 || val < 0)
 			err = -EINVAL;
 		else
 			tp->recvmsg_inq = val;
 		break;
 	case TCP_TX_DELAY:
 		if (val)
 			tcp_enable_tx_delay();
 		tp->tcp_tx_delay = val;
 		break;
 	default:
 		err = -ENOPROTOOPT;
 		break;
 	}

 	sockopt_release_sock(sk);
 	return err;
 }



